class Solution:
    def rangeAddQueries(self, n: int, queries: list[list[int]]) -> list[list[int]]:
        diff = [[0] * (n + 1) for _ in range(n + 1)]
        for r1, c1, r2, c2 in queries:
            diff[r1][c1] += 1
            diff[r1][c2 + 1] -= 1
            diff[r2 + 1][c1] -= 1
            diff[r2 + 1][c2 + 1] += 1
        mat = [[0] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                top = mat[r - 1][c] if r > 0 else 0
                left = mat[r][c - 1] if c > 0 else 0
                top_left = mat[r - 1][c - 1] if r > 0 and c > 0 else 0
                mat[r][c] = diff[r][c] + top + left - top_left
        return mat

class Solution {
public:
    std::vector<std::vector<int>> rangeAddQueries(int n, std::vector<std::vector<int>>& queries) {
        std::vector<std::vector<int>> diff(n + 1, std::vector<int>(n + 1, 0));
        for (const auto& q : queries) {
            int r1 = q[0], c1 = q[1], r2 = q[2], c2 = q[3];
            diff[r1][c1]++;
            diff[r1][c2 + 1]--;
            diff[r2 + 1][c1]--;
            diff[r2 + 1][c2 + 1]++;
        }
        std::vector<std::vector<int>> mat(n, std::vector<int>(n, 0));
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                int top = (r > 0) ? mat[r - 1][c] : 0;
                int left = (c > 0) ? mat[r][c - 1] : 0;
                int top_left = (r > 0 && c > 0) ? mat[r - 1][c - 1] : 0;
                mat[r][c] = diff[r][c] + top + left - top_left;
            }
        }
        return mat;
    }
};

